/** A search of one model, typed by it: `searchItems(client, search)` takes it */
export type SearchOf<N extends keyof Wheres> = Omit<SearchPattern, "type" | "where" | "orderBy"> & {
  type: N;
  where?: Wheres[N];
  orderBy?: SearchOrder<OrderFields[N]>[];
};
